const STORAGE_KEY = 'rc-theme';const THEMES = ['bear','dark','light','contrast','system'];const mediaQueryDark = window.matchMedia('(prefers-color-scheme:dark)');function resolveTheme(theme){return theme === 'system' ? (mediaQueryDark.matches ? 'dark':'light'):theme;}function applyTheme(theme){const html = document.documentElement;const applied = resolveTheme(theme);html.dataset.theme = applied;html.classList.toggle('dark',applied === 'dark');html.classList.toggle('contrast',applied === 'contrast');html.classList.toggle('bear',applied === 'bear');}function getStoredTheme(){const stored = localStorage.getItem(STORAGE_KEY);return THEMES.includes(stored) ? stored:'bear';}function saveTheme(theme){localStorage.setItem(STORAGE_KEY,theme);}function updateAriaLabel(button,theme){const appliedTheme = theme === 'system' ? `${resolveTheme(theme)}(system)`:theme;button.setAttribute('aria-label',`Switch theme (current:${appliedTheme})`);}function getNextTheme(currentTheme){const idx = THEMES.indexOf(currentTheme);return THEMES[(idx + 1) % THEMES.length];}export function initThemeToggle(btnSelector = '#theme-toggle'){const btn = document.querySelector(btnSelector);if (!btn) return;const initialTheme = getStoredTheme();applyTheme(initialTheme);updateAriaLabel(btn,initialTheme);btn.addEventListener('click',() =>{const currentTheme = getStoredTheme();const nextTheme = getNextTheme(currentTheme);saveTheme(nextTheme);applyTheme(nextTheme);updateAriaLabel(btn,nextTheme);});document.addEventListener('keydown',(e) =>{if (e.key.toLowerCase() === 't' && !e.ctrlKey && !e.metaKey){btn.click();}});mediaQueryDark.addEventListener('change',(e) =>{const storedTheme = getStoredTheme();if (storedTheme === 'system'){applyTheme('system');updateAriaLabel(btn,'system');}});}document.addEventListener('DOMContentLoaded',() =>{initThemeToggle('#theme-toggle');});